/**
 * Mounts — the single source of truth for all ~500 ultra-rare rideable creatures.
 *
 * 52 are PURCHASABLE with GOLD in the Stable (and also drop); the rest are drop-only
 * (1/8000 off any kill). Every mount grants +40% move speed, mints as an NFT,
 * and sells on the market like any item.
 *
 * Each spec carries a creature ARCHETYPE + FEATURE flags + a 4-colour palette so
 * the mesh builder (items/mesh.ts) renders them all with compact, varied code.
 */

export type MountArch = 'quad' | 'raptor' | 'drake'
export type MountFeature =
  | 'antlers' | 'tusks' | 'horn' | 'mane' | 'spikes' | 'ears' | 'frill' | 'wings' | 'plume'

export interface MountSpec {
  id: string
  name: string
  desc: string
  arch: MountArch
  features: readonly MountFeature[]
  /** [body, dark, belly, accent] hex. */
  pal: readonly [number, number, number, number]
  glow?: boolean
  /** GOLD price if purchasable in the Stable; omitted = drop-only. */
  buy?: number
}

const m = (
  id: string, name: string, arch: MountArch, features: readonly MountFeature[],
  pal: readonly [number, number, number, number], desc: string,
  opts?: { glow?: boolean; buy?: number }
): MountSpec => ({ id, name, arch, features, pal, desc, ...(opts?.glow ? { glow: true } : {}), ...(opts?.buy ? { buy: opts.buy } : {}) })

