export const MOUNT_SPECS: readonly MountSpec[] = [...PURCHASABLE, ...DROP_ONLY, ...NEW_PURCHASABLE, ...NEW_DROP_ONLY]
export const MOUNT_IDS: readonly string[] = MOUNT_SPECS.map((s) => s.id)
/** The 12 purchasable mounts with their GOLD prices (ascending). */
export const PURCHASABLE_MOUNTS: readonly { id: string; price: number }[] = [...PURCHASABLE, ...NEW_PURCHASABLE]
  .map((s) => ({ id: s.id, price: s.buy ?? 0 }))
  .sort((a, b) => a.price - b.price)
/** Cheapest purchasable mount — the grantable "starter" (also used for testing). */
export const STARTER_MOUNT_ID = 'mount_direwolf'

const BY_ID = new Map(MOUNT_SPECS.map((s) => [s.id, s]))
export function mountSpec(id: string): MountSpec | undefined {
  return BY_ID.get(id)
}
